/**
 * prune-orphan-wargear.ts — remove `wargear.json` entities referenced by nothing.
 *
 * Why: the retired army-assist prose lineage minted a `wargear` entity for every
 * option name its parser failed to resolve, laundering captured prose
 * ("gauss scalpel or tesla caster") into self-consistent garbage. Regenerating
 * `wargear-options.json` from BSData (convert-bsdata-wargear.ts) orphans those
 * fabricated ids. This pass removes any `wargear.json` item no surviving entity
 * references — unit `weapon_ids`, wargear-option `replaces`/`replacement`/
 * `replacement_choice`, or unit-composition `default_weapon_ids`.
 *
 * Reference counting is GLOBAL (a wargear id kept if used by ANY faction) — the
 * loadout resolver matches against the merged bundle, so an id used elsewhere must
 * survive everywhere. `weapons.json` is left untouched (real stat blocks, tracked
 * by the share registry); only the non-weapon `wargear.json` is pruned.
 *
 * Usage:
 *   npx tsx tools/src/prune-orphan-wargear.ts [--write]   (dry-run by default)
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const CORE_DIR = resolve(__dirname, "..", "..", "data", "core");

interface IdRecord {
  id: string;
}
interface Unit extends IdRecord {
  weapon_ids?: string[];
}
interface WargearOption {
  unit_id: string;
  replaces?: string[];
  replacement?: string[];
  replacement_choice?: string[][];
}
interface Composition {
  models?: { default_weapon_ids?: string[] }[];
}

function readJSON<T>(path: string): T[] {
  return existsSync(path) ? (JSON.parse(readFileSync(path, "utf-8")) as T[]) : [];
}

function repoDirs(): string[] {
  return readdirSync(CORE_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith("_"))
    .map((d) => d.name)
    .sort();
}

function main(): void {
  const write = process.argv.includes("--write");
  const dirs = repoDirs();

  // GLOBAL set of every weapon/wargear id referenced by a surviving entity.
  const referenced = new Set<string>();
  for (const dir of dirs) {
    for (const u of readJSON<Unit>(join(CORE_DIR, dir, "units.json"))) {
      for (const w of u.weapon_ids ?? []) referenced.add(w);
    }
    for (const o of readJSON<WargearOption>(join(CORE_DIR, dir, "wargear-options.json"))) {
      for (const w of o.replaces ?? []) referenced.add(w);
      for (const w of o.replacement ?? []) referenced.add(w);
      for (const grp of o.replacement_choice ?? []) for (const w of grp) referenced.add(w);
    }
    for (const c of readJSON<Composition>(join(CORE_DIR, dir, "unit-compositions.json"))) {
      for (const m of c.models ?? []) for (const w of m.default_weapon_ids ?? []) referenced.add(w);
    }
  }

  let totalRemoved = 0;
  for (const dir of dirs) {
    const path = join(CORE_DIR, dir, "wargear.json");
    const wargear = readJSON<IdRecord>(path);
    if (wargear.length === 0) continue;
    const kept = wargear.filter((w) => referenced.has(w.id));
    const removed = wargear.filter((w) => !referenced.has(w.id));
    if (removed.length === 0) continue;
    totalRemoved += removed.length;
    console.log(`${dir}: removing ${removed.length} orphaned wargear (${wargear.length} → ${kept.length})`);
    for (const r of removed) console.log(`    - ${r.id}`);
    if (write) writeFileSync(path, JSON.stringify(kept, null, 2) + "\n");
  }
  console.log(`\nTotal orphaned wargear removed: ${totalRemoved}`);
  if (!write) console.log("DRY RUN — re-run with --write to apply.");
}

main();
